pat <- "foreground:"
pos <- gregexpr(pat, .context$bslib_source, fixed = TRUE)[[1]]
res <- list()
if (pos[1] > 0) {
  for (i in seq_along(pos)) {
    start <- max(1, pos[i] - 200)
    end <- min(nchar(.context$bslib_source), pos[i] + 200)
    res[[i]] <- peek(.context$bslib_source, start = start, end = end)
  }
}

length(pos)

# Return the peeks (first 5 to keep output manageable)
head(res, 5)

