# Locate header for _brand-yml.scss and peek larger region
hdr_pat_full <- "# ---- FILE: /var/folders/98/rmspnd9s3zj36ncllv0x3n8w0000gn/T//RtmpjkvOaG/bslib/inst/brand/bs5/_brand-yml.scss ----"
start_pos <- regexpr(hdr_pat_full, .context$bslib_source, fixed = TRUE)[1]
if (start_pos > 0) {
  # peek from header start to header + 20000 chars
  peek1 <- peek(.context$bslib_source, start = start_pos, end = start_pos + 20000)
} else {
  peek1 <- NULL
}

# Also search for references to 'brand-yml' and 'brand.yml' in source
refs <- list(
  brand_yml_files = search(.context$bslib_source, "brand.yml"),
  brand_yml_scscss = search(.context$bslib_source, "brand-yml"),
  brand_yml_scss2 = search(.context$bslib_source, "_brand-yml.scss")
)

list(peek_header = substring(peek1, 1, 5000), refs = refs)

# locate FILE header for _brand-yml.scss
hdr_pattern <- "# ---- FILE: .*_brand-yml.scss ----\n"
hdr_loc <- regexpr(hdr_pattern, .context$bslib_source, perl = TRUE)
start <- as.integer(hdr_loc)

if (start > 0) {
  # find next FILE header after this one
  next_hdr_pos <- regexpr("# ---- FILE: ", substring(.context$bslib_source, start + 1), fixed = TRUE)[1]
  if (next_hdr_pos == -1) {
    end <- nchar(.context$bslib_source)
  } else {
    end <- start + next_hdr_pos - 1
  }
  # extract the file content
  file_contents <- substring(.context$bslib_source, start, end)
  # return the first 8000 chars for inspection
  result <- substring(file_contents, 1, 8000)
} else {
  result <- "_brand-yml.scss header not found"
}

list(start_pos = start, snippet = result)
